import { DataTable } from "@/components/portal";
import { Link, useGo } from "./link";
import type { ReactNode } from "react";
import { Check } from "lucide-react";
import { InnerPage, Status, instName } from "./portal";
import { useCurrentUser, useStore } from "@/lib/store";
import type { Application } from "@/lib/data";

export const WIZARD = [
  { slug: "details", label: "Application Details" },
  { slug: "checklist", label: "Document Checklist" },
  { slug: "documents", label: "Documents" },
  { slug: "validation", label: "Pre-Validation" },
  { slug: "review", label: "Review & Submit" },
] as const;

export function useApp(id: string) {
  return useStore((s) => s.applications.find((a) => a.id === id));
}

function NotFound({ id }: { id: string }) {
  return (
    <div className="notice">
      No application found with reference <b>{id}</b>.{" "}
      <Link to="/" className="link">
        Return to Home
      </Link>
    </div>
  );
}

/** Institution application page wrapper with ownership check and wizard step bar. */
export function InstitutionAppPage({
  id,
  step,
  title,
  children,
  allowPublic,
}: {
  id: string;
  step?: string;
  title: string;
  children: (a: Application) => ReactNode;
  allowPublic?: boolean;
}) {
  const a = useApp(id);
  const user = useCurrentUser();
  const crumbs = [
    { label: "My Applications", to: "/institution/applications" },
    { label: a?.ref ?? id, to: a ? `/institution/applications/${a.id}/status` : undefined },
    { label: title },
  ];
  return (
    <InnerPage role="institution" allowPublic={allowPublic} crumbs={crumbs} title={title}>
      {!a ? (
        <NotFound id={id} />
      ) : user && user.institutionId !== a.institutionId ? (
        <div className="notice">This application does not belong to your institution.</div>
      ) : (
        <>
          <div className="record-summary">
            <span>
              <b className="text-navy">Application ID:</b> {a.ref}
            </span>
            <span>
              <b className="text-navy">Institution:</b> {instName(a.institutionId)}
            </span>
            <span>
              <b className="text-navy">Type:</b> {a.type}
            </span>
            <span>
              <b className="text-navy">Status:</b> <Status s={a.status} />
            </span>
          </div>
          {step && (
            <ol className="flow-steps" aria-label="Application steps">
              {WIZARD.map((w, i) => (
                <li key={w.slug}>
                  <Link
                    to={`/institution/applications/${a.id}/${w.slug}`}
                    aria-current={w.slug === step ? "step" : undefined}
                    className={`flow-step ${w.slug === step ? "current" : ""} ${i < WIZARD.findIndex((w) => w.slug === step) ? "visited" : ""}`}
                  >
                    <span className="step-number">{i + 2}</span>
                    <span>
                      <small>Step {i + 2}</small>
                      {w.label}
                    </span>
                  </Link>
                </li>
              ))}
            </ol>
          )}
          {step && a.status !== "Draft" && (
            <div className="notice mb-4">
              This application was submitted on {a.submittedOn} and is frozen. The content below is
              read-only.{" "}
              <Link to={`/institution/records/${a.id}`} className="link">
                View submitted record
              </Link>
            </div>
          )}
          {children(a)}
          <div className="mt-6 flex flex-wrap gap-2 text-sm">
            <Link to={`/institution/applications/${a.id}/status`} className="btn btn-outline">
              Application Status
            </Link>
            <Link to={`/institution/applications/${a.id}/history`} className="btn btn-outline">
              Application History
            </Link>
          </div>
        </>
      )}
    </InnerPage>
  );
}

export function WizardNav({
  id,
  step,
  onNext,
  nextDisabled,
}: {
  id: string;
  step: string;
  onNext?: () => void;
  nextDisabled?: boolean;
}) {
  const go = useGo();
  const i = WIZARD.findIndex((w) => w.slug === step);
  const prev =
    i > 0
      ? `/institution/applications/${id}/${WIZARD[i - 1].slug}`
      : "/institution/applications/new";
  const next =
    i < WIZARD.length - 1 ? `/institution/applications/${id}/${WIZARD[i + 1].slug}` : null;
  return (
    <div className="flex justify-between mt-5">
      <Link to={prev} className="btn btn-outline">
        &larr; Previous
      </Link>
      {next && (
        <button
          className="btn btn-primary"
          disabled={nextDisabled}
          onClick={() => {
            onNext?.();
            go(next);
          }}
        >
          Save &amp; Continue &rarr;
        </button>
      )}
    </div>
  );
}

export const CASE_STEPS = [
  { slug: "overview", label: "Overview" },
  { slug: "evidence", label: "Evidence" },
  { slug: "authenticity", label: "Authenticity" },
  { slug: "compliance", label: "Compliance" },
  { slug: "inspection", label: "Inspection" },
  { slug: "review", label: "Review & Decision" },
] as const;

export function CasePage({
  id,
  step,
  children,
}: {
  id: string;
  step: string;
  children: (a: Application) => ReactNode;
}) {
  const a = useApp(id);
  const i = CASE_STEPS.findIndex((c) => c.slug === step);
  const cur = CASE_STEPS[i];
  return (
    <InnerPage
      role="officer"
      crumbs={[
        { label: "Case Queue", to: "/officer/queue" },
        { label: a?.ref ?? id, to: `/officer/cases/${id}/overview` },
        { label: cur.label },
      ]}
      title={cur.label}
    >
      {!a || a.status === "Draft" ? (
        <NotFound id={id} />
      ) : (
        <>
          <div className="record-summary">
            <span>
              <b className="text-navy">Institution:</b> {instName(a.institutionId)}
            </span>
            <span>
              <b className="text-navy">Type:</b> {a.type}
            </span>
            <span>
              <b className="text-navy">Assigned:</b> {a.assignedOfficer ?? "Unassigned"}
            </span>
            <span>
              <b className="text-navy">Status:</b> <Status s={a.status} />
            </span>
          </div>
          <ol className="flow-steps" aria-label="Application steps">
            {CASE_STEPS.map((c, j) => (
              <li key={c.slug}>
                <Link
                  to={`/officer/cases/${a.id}/${c.slug}`}
                  aria-current={c.slug === step ? "step" : undefined}
                  className={`flow-step ${c.slug === step ? "current" : ""}`}
                >
                  <span className="step-number">{j + 1}</span>
                  <span>
                    <small>Stage {j + 1}</small>
                    {c.label}
                  </span>
                </Link>
              </li>
            ))}
          </ol>
          {children(a)}
          <div className="flex justify-between mt-6">
            {i > 0 ? (
              <Link
                to={`/officer/cases/${a.id}/${CASE_STEPS[i - 1].slug}`}
                className="btn btn-outline"
              >
                &larr; {CASE_STEPS[i - 1].label}
              </Link>
            ) : (
              <Link to="/officer/queue" className="btn btn-outline">
                &larr; Case Queue
              </Link>
            )}
            {i < CASE_STEPS.length - 1 && (
              <Link
                to={`/officer/cases/${a.id}/${CASE_STEPS[i + 1].slug}`}
                className="btn btn-primary"
              >
                {CASE_STEPS[i + 1].label} &rarr;
              </Link>
            )}
          </div>
        </>
      )}
    </InnerPage>
  );
}

export function DetailsDL({ a, d = a.details }: { a: Application; d?: Application["details"] }) {
  return (
    <dl className="dl">
      <dt>Application ID</dt>
      <dd>{a.ref}</dd>
      <dt>Institution</dt>
      <dd>{instName(a.institutionId)}</dd>
      <dt>Application Type</dt>
      <dd>{a.type}</dd>
      <dt>Programme</dt>
      <dd>{d.programme}</dd>
      <dt>Course</dt>
      <dd>{d.course || "—"}</dd>
      <dt>Intake</dt>
      <dd>{d.intake}</dd>
      <dt>Academic Year</dt>
      <dd>{d.academicYear}</dd>
      <dt>Land Area</dt>
      <dd>{d.landArea} acres</dd>
      <dt>Built-up Area</dt>
      <dd>{d.builtUpArea} sq.m</dd>
      <dt>Full-time Faculty</dt>
      <dd>{d.facultyCount}</dd>
      <dt>Head of Institution</dt>
      <dd>{d.principal || "—"}</dd>
      <dt>Address</dt>
      <dd>{d.address || "—"}</dd>
      <dt>Submission Date</dt>
      <dd>{a.submittedOn ?? "Not submitted"}</dd>
    </dl>
  );
}

export function DocTable({
  docs,
  link,
}: {
  docs: Application["documents"];
  link?: (code: string) => ReactNode;
}) {
  return (
    <div className="overflow-x-auto">
      <DataTable className="gov-table">
        <thead>
          <tr>
            <th>Code</th>
            <th>Document</th>
            <th>Mandatory</th>
            <th>File</th>
            <th>Status</th>
            <th>Verification Report</th>
            {link && <th>Action</th>}
          </tr>
        </thead>
        <tbody>
          {docs.map((d) => (
            <tr key={d.code}>
              <td>{d.code}</td>
              <td>{d.name}</td>
              <td>{d.mandatory ? "Yes" : "No"}</td>
              <td>
                {d.fileName ?? "—"}
                {d.uploadedOn && (
                  <div className="text-xs text-muted-foreground">Uploaded {d.uploadedOn}</div>
                )}
              </td>
              <td>
                <Status s={d.status} />
              </td>
              <td className="text-xs">
                {d.checkedBy ? (
                  <>
                    <div>{d.findings}</div>
                    <div className="text-muted-foreground mt-1">
                      Checked by {d.checkedBy} on {d.checkedOn}
                    </div>
                  </>
                ) : d.status === "Under Review" ? (
                  "Verification pending"
                ) : (
                  "—"
                )}
              </td>
              {link && <td>{link(d.code)}</td>}
            </tr>
          ))}
        </tbody>
      </DataTable>
    </div>
  );
}

import { Link as RLink, useNavigate } from "@tanstack/react-router";
import type { AnchorHTMLAttributes, FC } from "react";

/** Router Link that accepts fully-resolved path strings (e.g. built from record IDs). */
export const Link = RLink as unknown as FC<
  Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> & {
    to: string;
    search?: Record<string, string>;
    activeProps?: { className?: string };
    activeOptions?: { exact?: boolean };
  }
>;

export function useGo() {
  const navigate = useNavigate();
  return (to: string) => navigate({ to: to as never });
}

import { useQuery } from "@tanstack/react-query";
import { api } from "@/features/api";
import { label } from "@/features/presentation";
import { useRouterState } from "@tanstack/react-router";
import { Link, useGo } from "./link";
import { useState, type ReactNode, type TableHTMLAttributes } from "react";
import {
  Accessibility,
  ArrowRight,
  Bell,
  BookOpen,
  ChevronRight,
  CircleHelp,
  ClipboardCheck,
  FileCheck2,
  FilePlus2,
  Files,
  LayoutDashboard,
  LogOut,
  Menu,
  Network,
  Search,
  Settings,
  ShieldCheck,
  Users,
  X,
  ChartNoAxesCombined,
  ScrollText,
  AlertCircle,
  type LucideIcon,
} from "lucide-react";
import { roleHome, userHome, useCurrentUser, useBackendSession } from "@/lib/backend-session";
import type { Role } from "@/lib/data";
import { institutions } from "@/lib/data";
import { PublicHeader, PublicFooter, PublicBrand } from "./public-chrome";

export function Brand() {
  return <PublicBrand />;
}
function setFont(delta: number) {
  const el = document.documentElement;
  const size = parseFloat(getComputedStyle(el).fontSize);
  el.style.fontSize = delta === 0 ? "16px" : `${Math.min(20, Math.max(13, size + delta))}px`;
}
export function Header() {
  const user = useCurrentUser();
  const go = useGo();
  const { logout } = useBackendSession();
  const notifications = useQuery({
    queryKey: ["notification-count", user?.id],
    queryFn: () => api<unknown[]>("/notifications?state=unread&page_size=1"),
    enabled: !!user,
    refetchInterval: 10000,
  });
  const unread = notifications.data?.meta.total;
  return (
    <>
      <a href="#main" className="skip-link">
        Skip to main content
      </a>
      <header className="site-header">
        <Brand />
        <nav aria-label="Primary" className="header-links">
          <Link to="/" activeOptions={{ exact: true }} activeProps={{ className: "is-current" }}>
            Overview
          </Link>
          <Link to="/notices">Portal notices</Link>
          <Link to="/resources">Resources</Link>
        </nav>
        <div className="flex items-center gap-3">
          <span className="year-chip">AY 2026–27</span>
          <details className="accessibility-menu">
            <summary className="icon-button" aria-label="Text size and accessibility">
              <Accessibility size={18} />
            </summary>
            <div>
              <span>Text size</span>
              <button type="button" onClick={() => setFont(-1)} aria-label="Decrease font size">
                A−
              </button>
              <button type="button" onClick={() => setFont(0)} aria-label="Reset font size">
                A
              </button>
              <button type="button" onClick={() => setFont(1)} aria-label="Increase font size">
                A+
              </button>
            </div>
          </details>
          {user ? (
            <>
              <Link
                to="/notifications"
                className="icon-button relative"
                aria-label={
                  unread === undefined ? "Notifications" : `Notifications, ${unread} unread`
                }
              >
                <Bell size={19} />
                {unread !== undefined && unread > 0 && <span className="notification-dot" />}
              </Link>
              <div className="header-profile">
                <span className="avatar">
                  {user.name
                    .split(" ")
                    .slice(-2)
                    .map((n) => n[0])
                    .join("")}
                </span>
                <span className="hidden lg:block">
                  <b>{user.name}</b>
                  <small>{user.roles.map((r) => label(r)).join(", ")}</small>
                </span>
              </div>
              <button
                className="icon-button"
                aria-label="Sign out"
                onClick={() => {
                  void logout().then(() => go("/login"));
                  go("/login");
                }}
              >
                <LogOut size={18} />
              </button>
            </>
          ) : (
            <Link to="/login" className="btn btn-navy">
              Sign in <ArrowRight size={15} />
            </Link>
          )}
        </div>
      </header>
      <div className="workspace-environment" role="note">
        Prototype workspace · Sample institutional records{" "}
        <Link to="/help">About verification limits</Link>
      </div>
    </>
  );
}
export function Footer() {
  return (
    <footer className="site-footer">
      <span>Uranium Verify · Development prototype</span>
      <div className="flex flex-wrap gap-5">
        <Link to="/help">Help centre</Link>
        <Link to="/resources">Application guidance</Link>
        <span>No live AICTE connection</span>
      </div>
    </footer>
  );
}
export function PublicShell({
  children,
  landing = false,
}: {
  children: ReactNode;
  landing?: boolean;
}) {
  return (
    <div className="uv-public min-h-screen flex flex-col">
      <PublicHeader />
      <main id="main" className={landing ? "uv-landing" : "public-main uv-content"}>
        {children}
      </main>
      <PublicFooter />
    </div>
  );
}
const NAV: Record<Role, { to: string; label: string; icon: LucideIcon }[]> = {
  institution: [
    { to: "/institution/dashboard", label: "Overview", icon: LayoutDashboard },
    { to: "/institution/applications", label: "My applications", icon: Files },
    { to: "/institution/applications/new", label: "New application", icon: FilePlus2 },
    { to: "/institution/history", label: "Approved records", icon: BookOpen },
    { to: "/institution/deficiencies", label: "Deficiencies", icon: AlertCircle },
    { to: "/notifications", label: "Notifications", icon: Bell },
    { to: "/settings", label: "Settings", icon: Settings },
  ],
  officer: [
    { to: "/officer/dashboard", label: "Overview", icon: LayoutDashboard },
    { to: "/officer/queue", label: "Case queue", icon: Files },
    { to: "/officer/verification-queue", label: "Document verification", icon: FileCheck2 },
    { to: "/officer/reports", label: "Reports & insights", icon: ChartNoAxesCombined },
    { to: "/resources", label: "Knowledge base", icon: BookOpen },
    { to: "/notifications", label: "Notifications", icon: Bell },
    { to: "/settings", label: "Settings", icon: Settings },
  ],
  admin: [
    { to: "/admin/notices", label: "Portal notices", icon: Bell },
    { to: "/admin/users", label: "Users & roles", icon: Users },
    { to: "/admin/rules", label: "Rule library", icon: ClipboardCheck },
    { to: "/admin/connectors", label: "Connectors", icon: Network },
    { to: "/admin/audit", label: "Audit trail", icon: ScrollText },
    { to: "/admin/knowledge-sources", label: "Knowledge sources", icon: BookOpen },
    { to: "/notifications", label: "Notifications", icon: Bell },
    { to: "/settings", label: "Settings", icon: Settings },
  ],
};
export type Crumb = { label: string; to?: string };
export function InnerPage({
  role,
  crumbs,
  title,
  children,
  allowPublic,
  actions: act,
}: {
  role?: Role | Role[];
  crumbs: Crumb[];
  title: string;
  children: ReactNode;
  allowPublic?: boolean;
  actions?: ReactNode;
}) {
  const user = useCurrentUser();
  const session = useBackendSession();
  const hydrated = !session.pending;
  const [open, setOpen] = useState(false);
  const path = useRouterState({ select: (s) => s.location.pathname });
  const roles = role ? (Array.isArray(role) ? role : [role]) : null;
  const descriptions: Record<string, string> = {
    "Institution Dashboard": "Your applications, progress, and next steps at a glance.",
    "Officer Dashboard": "A clear view of your review workload and what needs attention.",
    "My Applications": "Manage submissions and follow every stage of your approval journey.",
    "Case Queue": "Find, prioritise, and review institution applications.",
    "Users & Roles": "Manage access to your approval workspace.",
    "Pre-Validation": "Find the gaps, understand the rules, and prepare a complete submission.",
    Reports: "Download saved reports and share permitted summaries with institutions.",
    "Request Details":
      "Confirm your institution’s details and explain the changes you are requesting.",
    "Document Checklist":
      "See what is required, what is conditional, and which alternatives you can provide.",
    Documents: "Upload original documents and follow their safety and readability checks.",
    "Review & Submit": "Check your saved information before confirming submission.",
    "Application Status": "Follow your submission and see the next action needed.",
    "Case Overview":
      "Understand the request, review key findings, and open the supporting evidence.",
    "Evidence Viewer":
      "Compare extracted information with the original document and record corrections.",
    "Document Authenticity": "Review issuer responses, signatures and provenance separately.",
    "Compliance Review": "Run applicable rules and review the evidence behind each result.",
    "Infrastructure & Inspection":
      "Compare declared measurements with supporting evidence and identify inspection needs.",
    "Review & Decision":
      "Record your assessment, request clarification, or route further verification.",
    "Document Verification": "Review assigned verification tasks and record a sourced response.",
    "Approved Records": "Compare previous approvals with the changes currently requested.",
    "Knowledge Sources": "Review and publish source versions used in regulatory explanations.",
    "New Application": "Choose the institution, academic year, and application category.",
    "Portal notices": "Keep institutions informed with clear, timely updates.",
    "Rule Library": "Review, test, and publish versioned compliance rules.",
    "Audit Trail": "Review who changed a record, when it changed, and why.",
    Connectors: "Explore demonstration configurations for external sources.",
    Settings: "Your profile, preferences, and account settings.",
  };
  let body: ReactNode;
  if (!hydrated)
    body = (
      <div className="loading-state" role="status">
        <span className="loading-dot" /> Preparing your workspace…
      </div>
    );
  else if (session.error)
    body = (
      <div role="alert">
        <p>The service is unavailable. Your saved work has not been changed.</p>
        <button className="btn btn-navy" onClick={session.retry}>
          Retry connection
        </button>
      </div>
    );
  else if (!user && !allowPublic && roles) body = <AuthRequired />;
  else if (user && roles && !roles.includes(user.role)) body = <AccessDenied />;
  else
    body = (
      <>
        <div className="page-heading">
          <div>
            <span className="eyebrow">
              {user ? `${user.role} workspace` : "Application portal"}
            </span>
            <h1>
              {title === "Institution Dashboard" || title === "Officer Dashboard"
                ? "Workspace overview"
                : title}
            </h1>
            <p>{descriptions[title] ?? "Review information and manage your next steps."}</p>
          </div>
          {act}
        </div>
        <div className="page-content">{children}</div>
      </>
    );
  const nav = user
    ? NAV[user.role].filter((n) => {
        if (user.roles.includes("auditor") && !user.roles.includes("admin"))
          return ["/admin/audit", "/notifications", "/settings"].includes(n.to);
        if (
          user.roles.includes("specialist") &&
          !user.roles.some((r) => ["officer", "supervisor"].includes(r))
        )
          return [
            "/officer/verification-queue",
            "/resources",
            "/notifications",
            "/settings",
          ].includes(n.to);
        return true;
      })
    : null;
  return (
    <div className="uv-workspace min-h-screen flex flex-col">
      <Header />
      <div className={`workspace ${nav ? "has-sidebar" : ""}`}>
        {nav && (
          <>
            <button
              className="mobile-menu btn btn-outline"
              aria-expanded={open}
              aria-controls="workspace-sidebar"
              onClick={() => setOpen(!open)}
            >
              {open ? <X size={17} /> : <Menu size={17} />} Workspace menu
            </button>
            <aside
              id="workspace-sidebar"
              className={`workspace-sidebar ${open ? "is-open" : ""}`}
              aria-label="Section navigation"
            >
              <div className="workspace-label">
                YOUR WORKSPACE
                <span>
                  {user?.role === "officer"
                    ? "Review & scrutiny"
                    : user?.role === "admin"
                      ? "Portal administration"
                      : "Institution"}
                </span>
              </div>
              <nav>
                {nav.map((n) => {
                  const active =
                    path.replace(/\/$/, "") === n.to ||
                    (n.to === "/institution/applications" &&
                      path.startsWith(n.to + "/") &&
                      !path.endsWith("/new")) ||
                    (n.to === "/institution/deficiencies" && path.startsWith(n.to + "/")) ||
                    (n.to === "/officer/queue" && path.startsWith("/officer/cases/"));
                  return (
                    <Link
                      key={n.to}
                      to={n.to}
                      aria-current={active ? "page" : undefined}
                      onClick={() => setOpen(false)}
                      className={`sidebar-link ${active ? "active" : ""}`}
                    >
                      <n.icon size={18} strokeWidth={1.8} />
                      {n.label}
                      {active && <span className="active-dot" />}
                    </Link>
                  );
                })}
              </nav>
              <div className="sidebar-help">
                <span className="help-icon">
                  <CircleHelp size={21} />
                </span>
                <b>A little guidance?</b>
                <p>A clear next step starts with the right guidance.</p>
                <Link to="/help">
                  Visit the help centre <ArrowRight size={14} />
                </Link>
              </div>
              <div className="sidebar-bottom">
                <span className="status-led" />
                Academic year 2026–27
              </div>
            </aside>
          </>
        )}
        <main id="main" className="workspace-main">
          <nav aria-label="Breadcrumb" className="breadcrumb">
            <Link to="/">Portal</Link>
            {crumbs.map((c, i) => (
              <span key={i}>
                <ChevronRight size={12} />
                {c.to ? <Link to={c.to}>{c.label}</Link> : <span>{c.label}</span>}
              </span>
            ))}
          </nav>
