import { Link as PortalLink } from "@/components/link";
import { useNavigate as useRouterNavigate, useRouterState } from "@tanstack/react-router";
import type { AnchorHTMLAttributes } from "react";

/** Translate the source workflow routes into the approved portal's route structure. */
export function portalPath(path: string) {
  return path
    .replace(/^\/institution\/history\/([^/?]+)/, "/institution/records/$1")
    .replace(/^\/admin\/knowledge(?=\?|$)/, "/admin/knowledge-sources")
    .replace(/^\/officer\/applications(?=\/|\?|$)/, "/officer/cases")
    .replace(/^\/officer\/cases(?=\?|$)/, "/officer/queue")
    .replace(/^\/officer\/verifications/, "/officer/verification-queue")
    .replace(/^\/admin\/users-roles/, "/admin/users")
    .replace(/^\/admin\/integrations/, "/admin/connectors")
    .replace(/\/review-submit(?=\?|$)/, "/review")
    .replace(/^(\/institution\/deficiencies\/[^/?]+)(?=\?|$)/, "$1/respond");
}
type Props = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> & { to: string; end?: boolean };
export function Link({ to, end: _end, ...props }: Props) {
  const [pathname, query = ""] = portalPath(to).split("?");
  return (
    <PortalLink to={pathname} search={Object.fromEntries(new URLSearchParams(query))} {...props} />
  );
}
export const NavLink = Link;
export function useNavigate() {
  const navigate = useRouterNavigate();
  return (path: string, options?: { replace?: boolean }) => {
    const [to, query = ""] = portalPath(path).split("?");
    return navigate({
      to: to as never,
      search: Object.fromEntries(new URLSearchParams(query)) as never,
      replace: options?.replace,
    });
  };
}
export function useSearchParams(): [
  URLSearchParams,
  (next: URLSearchParams | Record<string, string>, options?: { replace?: boolean }) => void,
] {
  const location = useRouterState({ select: (s) => s.location });
  const navigate = useNavigate();
  return [
    new URLSearchParams(location.searchStr),
    (next, options) => {
      void navigate(`${location.pathname}?${new URLSearchParams(next)}`, options);
    },
  ];
}

import { api } from "../api";
import { Button } from "../components/ui/button";
import { Card } from "../components/ui/card";
import { label } from "../presentation";
export type Row = Record<string, unknown>;
export const rows = (value: unknown): Row[] => (Array.isArray(value) ? (value as Row[]) : []);
export const record = (value: unknown): Row =>
  value && typeof value === "object" && !Array.isArray(value) ? (value as Row) : {};
export const value = (input: unknown): string =>
  input == null ? "Unknown" : typeof input === "object" ? JSON.stringify(input) : String(input);
export const options = (body: unknown) => ({
  method: "POST",
  headers: { "Idempotency-Key": crypto.randomUUID() },
  body: JSON.stringify(body),
});
export const mutate = (path: string, body: unknown) => api<Row>(path, options(body));
export function Fields({ data }: { data: Row }) {
  return (
    <dl className="details">
      {Object.entries(data).map(([key, item]) => (
        <div key={key}>
          <dt>{label(key)}</dt>
          <dd>
            <ReadableValue item={item} />
          </dd>
        </div>
      ))}
    </dl>
  );
}
function ReadableValue({ item }: { item: unknown }) {
  if (item == null) return <>Not available</>;
  if (typeof item === "boolean") return <>{item ? "Yes" : "No"}</>;
  if (Array.isArray(item))
    return item.length ? (
      <ul className="readable-list">
        {item.map((v, i) => (
          <li key={i}>
            <ReadableValue item={v} />
          </li>
        ))}
      </ul>
    ) : (
      <>None recorded</>
    );
  if (typeof item === "object") return <Fields data={item as Row} />;
  const text = String(item);
  if (/^https:\/\//.test(text))
    return (
      <a href={text} target="_blank" rel="noreferrer">
        View source ↗
      </a>
    );
  return <>{/^[A-Z][A-Z_]+$/.test(text) ? label(text) : text}</>;
}
export function Loading({ error, retry }: { error?: Error | null; retry?: () => void }) {
  return (
    <Card>
      {error ? (
        <>
          <p role="alert">{error.message}</p>
          <Button onClick={retry}>Retry</Button>
        </>
      ) : (
        <p role="status">Loading authorized records…</p>
      )}
    </Card>
  );
}

import { createContext, useContext, useEffect, type ReactNode } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { api, ApiError, type User } from "@/features/api";
import { portalPath } from "@/features/navigation";

export type PortalRole = "institution" | "officer" | "admin";
export function workspaceRole(user: User): PortalRole {
  if (user.roles.some((r) => r.startsWith("institution_"))) return "institution";
  if (user.roles.some((r) => ["officer", "specialist", "supervisor"].includes(r))) return "officer";
  return "admin";
}
export type PortalUser = User & { role: PortalRole };
const SessionContext = createContext<{
  user: PortalUser | null;
  pending: boolean;
  error: Error | null;
  login: (email: string, password: string) => Promise<User>;
  logout: () => Promise<void>;
  retry: () => void;
} | null>(null);
export function BackendSessionProvider({ children }: { children: ReactNode }) {
  const qc = useQueryClient();
  const q = useQuery({
    queryKey: ["backend-session"],
    retry: false,
    staleTime: 30000,
    queryFn: async () => {
      try {
        return (await api<User>("/me")).data;
      } catch (e) {
        if (e instanceof ApiError && e.status === 401) return null;
        throw e;
      }
    },
  });
  useEffect(() => {
    const clear = () => {
      qc.clear();
      qc.setQueryData(["backend-session"], null);
    };
    window.addEventListener("uranium:session-expired", clear);
    return () => window.removeEventListener("uranium:session-expired", clear);
  }, [qc]);
  const user = q.data ? { ...q.data, role: workspaceRole(q.data) } : null;
  return (
    <SessionContext.Provider
      value={{
        user,
        pending: q.isPending,
        error: q.error,
        retry: () => {
          void q.refetch();
        },
        login: async (email, password) => {
          const result = await api<User>("/auth/session", {
            method: "POST",
            body: JSON.stringify({ email, password }),
          });
          qc.clear();
          qc.setQueryData(["backend-session"], result.data);
          return result.data;
        },
        logout: async () => {
          await api("/auth/session", { method: "DELETE" });
          qc.clear();
          qc.setQueryData(["backend-session"], null);
        },
      }}
    >
      {children}
    </SessionContext.Provider>
  );
}
export function useBackendSession() {
  const session = useContext(SessionContext);
  if (!session) throw new Error("Session provider missing");
  return session;
}
export const useCurrentUser = () => useBackendSession().user;
export const roleHome = {
  institution: "/institution/dashboard",
  officer: "/officer/dashboard",
  admin: "/admin/users",
};
export const userHome = (user: User) => portalPath(user.landing);
